<?php
require_once __DIR__ . '/payment-common.php';
function jc_hash(array $fields,string $salt): string {$values=[];foreach($fields as $k=>$v){if($k==='pp_SecureHash'||(!str_starts_with((string)$k,'pp_')&&!str_starts_with((string)$k,'ppmpf_'))||(string)$v==='')continue;$values[(string)$k]=(string)$v;}ksort($values,SORT_STRING);return hash_hmac('sha256',$salt.'&'.implode('&',array_values($values)),$salt);}
function jc_urls(): array {$live=strtolower(app_env('JAZZCASH_ENV','sandbox'))==='live';return $live?['wallet'=>'https://payments.jazzcash.com.pk/ApplicationAPI/API/2.0/Purchase/DoMWalletTransaction','hosted'=>'https://payments.jazzcash.com.pk/CustomerPortal/transactionmanagement/merchantform']:['wallet'=>'https://sandbox.jazzcash.com.pk/ApplicationAPI/API/2.0/Purchase/DoMWalletTransaction','hosted'=>'https://sandbox.jazzcash.com.pk/CustomerPortal/transactionmanagement/merchantform'];}
function jc_fields(array $o,string $ref): array {$now=new DateTimeImmutable('now',new DateTimeZone('Asia/Karachi'));$return=rtrim(app_env('APP_URL'),'/').'/api/jazzcash.php?action=return';return['pp_Version'=>'1.1','pp_TxnType'=>'MWALLET','pp_Language'=>'EN','pp_MerchantID'=>app_env('JAZZCASH_MERCHANT_ID'),'pp_Password'=>app_env('JAZZCASH_PASSWORD'),'pp_TxnCurrency'=>'PKR','pp_TxnDateTime'=>$now->format('YmdHis'),'pp_TxnExpiryDateTime'=>$now->modify('+1 day')->format('YmdHis'),'pp_TxnRefNo'=>$ref,'pp_BillReference'=>$o['order_no'],'pp_Description'=>'Zulfaan '.$o['order_no'],'pp_Amount'=>(string)((int)$o['total']*100),'pp_ReturnURL'=>$return];}
function jc_callback(array $d): array {$salt=app_env('JAZZCASH_INTEGRITY_SALT');$given=strtolower((string)($d['pp_SecureHash']??''));if($given===''||!hash_equals(jc_hash($d,$salt),$given))return['ok'=>false,'paid'=>false,'error'=>'JazzCash signature verification failed'];$no=(string)($d['pp_BillReference']??$d['ppmpf_1']??'');$code=(string)($d['pp_ResponseCode']??'');$paid=$code==='000';if($paid&&$no!=='')mark_order_paid($no,(string)($d['pp_TxnRefNo']??''));return['ok'=>true,'paid'=>$paid,'order_no'=>$no,'message'=>$paid?'Payment received':(string)($d['pp_ResponseMessage']??'Payment pending')];}
if(($_GET['action']??'')==='return'){if(($_SERVER['REQUEST_METHOD']??'')!=='POST')api_json(405,['ok'=>false,'error'=>'Invalid callback']);$r=jc_callback($_POST);if(!$r['ok'])api_json(400,$r);header('Location: '.app_env('APP_URL').'/checkout.html?payment='.($r['paid']?'paid':'pending').'&order_no='.rawurlencode($r['order_no']));exit;}
api_method('POST');$in=api_input();try{$no=(string)($in['order_no']??'');$o=payment_order($no);if($o['payment_method']!=='jazzcash')api_json(422,['ok'=>false,'error'=>'Payment method mismatch']);$salt=app_env('JAZZCASH_INTEGRITY_SALT');if($salt==='')api_json(503,['ok'=>false,'error'=>'JazzCash credentials are not configured']);$urls=jc_urls();$action=(string)($in['action']??'');if($action==='hosted'){$f=jc_fields($o,order_prefix($o['order_no'],'JC'));$f['ppmpf_1']=$o['order_no'];$f['pp_SecureHash']=jc_hash($f,$salt);api_json(200,['ok'=>true,'url'=>$urls['hosted'],'fields'=>$f]);}if($action==='mwallet'){$mobile=preg_replace('/\D/','',(string)($in['mobile']??''));$cnic=preg_replace('/\D/','',(string)($in['cnic6']??''));if(!preg_match('/^03\d{9}$/',$mobile)||!preg_match('/^\d{6}$/',$cnic))api_json(422,['ok'=>false,'error'=>'Enter a valid mobile and CNIC last six digits']);$f=jc_fields($o,order_prefix($o['order_no'],'JC').'-'.bin2hex(random_bytes(3)));$f['pp_MobileNumber']=$mobile;$f['pp_CNIC']=$cnic;$f['pp_SecureHash']=jc_hash($f,$salt);$res=gateway_post($urls['wallet'],['Content-Type: application/json','Accept: application/json'],json_encode($f));$d=$res['data'];$code=(string)($d['pp_ResponseCode']??'');$paid=$code==='000';if($paid)mark_order_paid($no,(string)($d['pp_TxnRefNo']??$f['pp_TxnRefNo']));api_json(200,['ok'=>true,'paid'=>$paid,'order_no'=>$no,'message'=>$paid?'Payment received':(string)($d['pp_ResponseMessage']??'JazzCash payment failed')]);}api_json(422,['ok'=>false,'error'=>'Unknown JazzCash action']);}catch(Throwable $e){api_json(502,['ok'=>false,'error'=>$e->getMessage()]);}
